# Hand-written explanations of the server options (Auth2Options, configuration section "Auth2"). Examples are written as appsettings.json under "Auth2".
N = {}
def n(path, what, when, why, ex=None): N[path] = dict(what=what, when=when, why=why, ex=ex)

n('Mode', 'One server for **many projects** (`MultiProject`) or for exactly one (`SingleProject`). Prefer calling `ServerWithSingleProject()` in `Program.cs`; the setting names the same thing. See [enums-reference.md](enums-reference.md#servermode).', 'Single mode for one product with one set of users; multi for several tenants.', 'It changes how the project of a request is found and where credentials live.', 'SingleProject')
n('CredentialScope', 'Where passwords and two-factor live by default: in each project (`PerProject`) or once per person (`Shared`). Single mode always uses `Shared`. See [credential-scope.md](credential-scope.md).', 'Decide once, before users register.', 'It decides whether the same email can have different passwords in different projects. Changing it later makes existing passwords unreadable.', 'Shared')
n('AllowCredentialScopeOverride', 'Lets a project choose its own `CredentialScope` (the project setting of the same name).', 'Only in rare mixed set-ups.', 'Off by default so that all projects behave the same.', True)
n('Issuer', 'The public address of the Server, for example `https://auth.example.com`. It is the `iss` of every token and the base of links in emails. **Required in Production and it must be `https`.** When empty (development) the address of the request is used.', 'Always set it in production.', 'A token is only valid for the issuer that made it; a wrong issuer breaks every client.', 'https://auth.example.com')
n('AutoSeed', 'Run the seeder at start outside Development (creates `_global`, the admin, the sample data).', 'First start of a new environment.', 'Better: run the `seed` command once and leave this off.', False)
n('AutoMigrate', 'Apply the database migrations at start outside Development.', 'Small deployments with one instance.', 'With several instances run `migrate` as a separate step instead: it uses a database lock and is safer.', False)
n('ProjectStatusCacheSeconds', 'How long the enabled/disabled status of a project or application is cached (seconds). A change on the same instance is seen at once; other instances learn through Redis or when the time ends.', 'Lower it if a disabled project must stop everywhere sooner; tests use 0.', 'Every token check asks for the status; the cache keeps that cheap.', 5)
n('SingleProject.Name', 'The name of the one project in single mode (its application is named `default`).', 'When you start a single-project server.', 'Shown in the admin pages and used to make the project key.', 'PaperTrade')
n('Messaging.Email.Provider', 'The server-wide default email provider: `logging`, `smtp`, `google` or your own. A project or application can choose another. See [email-and-sms.md](email-and-sms.md).', 'To send real email by default.', 'The last fallback after application and project.', 'google')
n('Messaging.Email.Host', 'SMTP host (not used by `google`).', 'With `smtp`.', 'Where mail is handed in.', 'smtp.example.com')
n('Messaging.Email.Port', 'SMTP port.', 'Match the security mode.', '587 for STARTTLS, 465 for TLS.', 587)
n('Messaging.Email.Security', 'Connection security: `StartTls`, `SslOnConnect` or `None`. See [enums-reference.md](enums-reference.md#smtpsecurity).', '`None` only for a trusted local relay.', '`None` sends the password in clear text.', 'StartTls')
n('Messaging.Email.UserName', 'SMTP login (for `google` the Gmail address).', 'When the server needs a login.', 'Authenticates the sender.', 'mail@example.com')
n('Messaging.Email.Password', 'SMTP password in clear text. **Keep it in an environment variable or a secret store**, never in a file in the repository (`Auth2__Messaging__Email__Password`).', 'Set it from the environment.', 'This value is not encrypted by the Server because it comes from configuration.', None)
n('Messaging.Email.FromAddress', 'The From address.', 'Always for `smtp`.', 'Receivers check it.', 'noreply@example.com')
n('Messaging.Email.FromName', 'The From display name (empty: the project brand or name).', 'To control the sender name.', 'Recognisable senders get fewer spam reports.', 'My Auth')
n('Messaging.Email.TimeoutSeconds', 'Time limit of one send.', 'Slow relays.', 'A stuck mail server must not hold a request.', 20)
n('Messaging.SmsProvider', 'The server-wide default SMS provider (`logging` unless you register your own `ISmsTransport`).', 'When you add a real SMS provider.', 'Same idea as email.', 'logging')
n('Messaging.SmsSender', 'The default SMS sender id.', 'With a real provider.', 'Branded sender ids build trust.', 'MyAuth')
n('Development.LogMessageBodies', 'In the **Development** environment only: the logging email and SMS senders also write the message body (links and codes) to the log.', 'On a developer machine when you need to click the confirmation link.', 'Without it the logs never show a link or a code. Never turn it on elsewhere: the log would hold the secrets.', True)
n('Redis.ConnectionString', 'The Redis connection string. When set, Redis shares rate-limit counters, one-time codes and settings invalidation between instances.', 'As soon as you run more than one instance.', 'Without it each instance counts alone. See [deployment-and-scaling.md](deployment-and-scaling.md).', 'redis:6379,password=secret')
n('Redis.KeyPrefix', 'A prefix for every key the Server writes.', 'Several servers share one Redis.', 'Keeps them apart.', 'auth2-prod')
n('Redis.Enabled', 'True when a connection string is set (read only: it is computed).', 'Never set it.', 'Tells the Server whether to use Redis.', None)
n('RateLimiting.Enabled', 'Turns the rate limiter on or off.', 'Off only in tests.', 'It slows guessing and floods ([security.md](security.md)).', True)
n('RateLimiting.Policies', 'A dictionary of named rules (`login`, `token`, `register`, `otp`, `password-reset`, `handshake`, `permission-sync`, `admin`, `passkey`, ...) with `PermitLimit` and `WindowSeconds` (default window 60 s). An entry replaces the built-in rule of that name.', 'Tighten `login`, loosen `permission-sync` for big fleets.', 'Each kind of request has its own risk and volume.', '={ "login": { "PermitLimit": 5, "WindowSeconds": 60 } }')
n('Security.RequireHttps', 'Redirect HTTP to HTTPS and send HSTS. `null` means "on outside Development and Testing".', 'Turn off only behind a proxy that already does it.', 'Tokens and cookies must not travel in clear text.', True)
n('Security.UseForwardedHeaders', 'Trust the `X-Forwarded-*` headers of a proxy (client address and scheme). **Turn on behind a proxy.**', 'Behind nginx, a load balancer, Kubernetes ingress.', 'Without it rate limits count the proxy\'s address and links get the wrong scheme.', True)
n('Security.TrustAllProxies', 'Accept forwarded headers from **any** sender. Use only when the Server cannot be reached except through your proxy.', 'Private networks.', 'Otherwise anyone could forge their address.', False)
n('Security.KnownProxies', 'The addresses of the proxies whose forwarded headers are trusted.', 'Prefer this to `TrustAllProxies`.', 'Trust only what you run.', ['10.0.0.5'])
n('Security.ContentSecurityPolicy', 'The `Content-Security-Policy` header of the pages. `{nonce}` is replaced by a fresh value per response and applied to the style block. The default allows only the Server\'s own scripts and styles.', 'When you add an external script or font (keep it as narrow as possible).', 'A strict policy stops injected scripts from running. Loosening it (`unsafe-inline`) weakens that protection.', "default-src 'self'; script-src 'self'; style-src 'self' 'nonce-{nonce}'; img-src 'self' data:")
n('Jobs.Enabled', 'Runs the maintenance jobs (one-time code cleanup, audit retention, token pruning, key removal).', 'Off only if you run them elsewhere.', 'Keeps the database small and retired keys removed.', True)
n('Jobs.IntervalMinutes', 'How often the jobs run (minutes).', 'Rarely.', 'One instance runs a job at a time (a database lock).', 30)
n('Jobs.AuditRetentionDays', 'Audit events older than this are deleted (0 keeps everything).', 'Set to your legal retention time.', 'The audit table grows without bound otherwise.', 180)
n('ExternalProviders.PollSeconds', 'How often every instance asks the database whether provider settings changed (a safety net next to Redis).', 'Lower it for faster reload without Redis.', 'A change must reach all instances; the poll guarantees it.', 15)
n('ExternalProviders.AllowPrivateNetworks', 'Lets the Server\'s outgoing HTTP calls to providers reach private addresses (10.x, 192.168.x, localhost).', '**Only in development**, or for an identity provider that is really on your private network.', 'The guard blocks private addresses so that a provider setting cannot be used to probe your network (SSRF).', True)
n('ExternalProviders.StateMinutes', 'How long a started external sign-in may take before its state expires.', 'Slow multi-factor providers.', 'A short window limits replay.', 15)
n('Passkeys.ServerDomain', 'The domain passkeys are bound to (the "relying party id"), for example `auth.example.com`. **Required in Production; never change it later**: every passkey made for the old domain stops working.', 'Before you turn passkeys on.', 'A passkey only works for the website it was made for.', 'auth.example.com')
n('Passkeys.BlockedAaguids', 'Authenticator models (AAGUID) that cannot be registered. Joined with the list an admin edits at run time (`server_values`).', 'To block a model with a known weakness.', 'Existing passkeys of a blocked model stay listed so that they can be removed.', ['00000000-0000-0000-0000-000000000000'])
n('Passkeys.AttestationMode', '`None` (default: the model is read as the authenticator reports it) or `AaguidAllowList` (only the models in `AllowedAaguids`).', 'When only company-issued security keys are allowed.', 'Attestation is not verified cryptographically in v1; the allow list is a policy on the reported model.', 'AaguidAllowList')
n('Passkeys.AllowedAaguids', 'The models accepted with `AttestationMode = AaguidAllowList`.', 'With the allow-list mode.', 'Restrict passkeys to approved devices.', ['00000000-0000-0000-0000-000000000000'])
